    "id": "sop-acc-01",
    "code": "SOP-ACC-01",
    "module": "accounting",
    "moduleName": "محاسبة التكاليف الصناعية والأستاذ (Accounting)",
    "role": "رئيس مراقبي التكاليف الصناعية",
    "title": "معايرة تكلفة ساعات تشغيل ماكينات المصنع ومعدلات الأجور",
    "objective": "مراجعة وتحديث معدلات تحميل ساعات الماكينات وتكلفة العمالة المباشرة في كافة مراكز الإنتاج بأودو.",
    "prerequisites": "فواتير كهرباء المصنع المعتمدة؛ جداول إهلاك الماكينات؛ سجلات صيانة المعدات؛ مسيرات الرواتب الفعلية.",
    "steps": [
      "الدخول إلى أودو ← التصنيع ← الإعدادات ← مراكز العمل (Work Centers).",
      "اختيار مركز العمل المستهدف (مثال: 'RUH-CNC-01: ماكينة هولزر خماسية المحاور').",
      "حساب تكلفة الكهرباء لكل ساعة تشغيل بناءً على قدرة الماكينة (28 كيلوواط) والتعرفة الصناعية (0.18 ريال/كيلوواط.ساعة).",
      "إضافة مخصص إهلاك ريش وأدوات القطع ومخصص الصيانة الوقائية السنوي مقسوماً على ساعات العمل المخططة.",
      "إدخال 'التكلفة لكل ساعة' المحسوبة (مثال: 145.00 ريال/ساعة) في تبويب المعلومات العامة.",
      "تحديث معدل تكلفة أجور مشغلي الـ CNC المعتمدين المباشرة (مثال: 65.00 ريال/ساعة).",
      "حفظ التعديلات وتفعيل أمر إعادة حساب تكلفة شجرة المواد للمنتجات المرتبطة بهذا المركز."
    ],
    "verification": "يجب أن تعكس تقارير تحليل تكلفة أمر التصنيع معدلات تحميل الماكينات والأجور المحدثة بدقة.",
    "caution": "يحظر احتساب تكلفة الساعة على أساس طاقة نظرية 24 ساعة؛ يجب الاعتماد على ساعات التشغيل الواقعية بعد استبعاد فترات التوقف."
